DECLARE
    CURSOR c_clients IS
        SELECT nom, ville FROM clients;
    v_nom   clients.nom%TYPE;
    v_ville clients.ville%TYPE;
BEGIN
    OPEN c_clients;
    LOOP
        FETCH c_clients INTO v_nom, v_ville;
        EXIT WHEN c_clients%NOTFOUND;
        DBMS_OUTPUT.PUT_LINE(v_nom || ' habite à ' || v_ville);
    END LOOP;
    CLOSE c_clients;
END;

