DECLARE
    v_nom clients.nom%TYPE;
BEGIN
    SELECT nom INTO v_nom FROM clients WHERE id = 999;
    DBMS_OUTPUT.PUT_LINE('Trouvé : ' || v_nom);
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Aucun client trouvé avec cet identifiant.');
    WHEN TOO_MANY_ROWS THEN
        DBMS_OUTPUT.PUT_LINE('Erreur : plusieurs clients portent cet id !');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Autre erreur : ' || SQLERRM);
END;

