CREATE OR REPLACE FUNCTION calculer_tva(p_montant IN NUMBER)
RETURN NUMBER
IS
    v_taux CONSTANT NUMBER := 0.18;
BEGIN
    RETURN p_montant * v_taux;
END;
/

CREATE OR REPLACE PROCEDURE augmenter_salaire(
    p_emp_id IN employes.id%TYPE,
    p_taux   IN NUMBER
)
IS
BEGIN
    UPDATE employes
    SET    salaire = salaire * (1 + p_taux)
    WHERE  id = p_emp_id;
    COMMIT;
END;
/
